import sys

def solve_lukas_problem():
    N = int(sys.stdin.readline())
    ring = [int(sys.stdin.readline()) for _ in range(N)]

    original_ring = [0] * N
    for i in range(N):
        original_ring[i] = ring[i] - ring[(i-1) % N] - ring[(i+1) % N]

    for num in original_ring:
        print(num)

if __name__ == "__main__":
    solve_lukas_problem()

